import unittest
from urls import canonical_url


class TestCanonicalUrl(unittest.TestCase):
    def test_basic_http(self):
        self.assertEqual(canonical_url("http://example.com"), "http://example.com")

    def test_basic_https(self):
        self.assertEqual(canonical_url("https://example.com"), "https://example.com")

    def test_lowercase_scheme_and_host(self):
        self.assertEqual(canonical_url("HTTP://EXAMPLE.COM"), "http://example.com")

    def test_remove_fragment(self):
        self.assertEqual(canonical_url("http://example.com#section"), "http://example.com")

    def test_remove_trailing_slash(self):
        self.assertEqual(canonical_url("http://example.com/path/"), "http://example.com/path")

    def test_preserve_query(self):
        self.assertEqual(canonical_url("http://example.com?a=1&b=2"), "http://example.com?a=1&b=2")

    def test_combined_normalization(self):
        self.assertEqual(
            canonical_url("HTTP://Example.COM/Path/?#frag?query=value"),
            "http://example.com/Path/??query=value"
        )

    def test_reject_non_string(self):
        with self.assertRaises(ValueError):
            canonical_url(123)

    def test_reject_missing_host(self):
        with self.assertRaises(ValueError):
            canonical_url("http:///example.com")

    def test_reject_other_schemes(self):
        with self.assertRaises(ValueError):
            canonical_url("ftp://example.com")


if __name__ == "__main__":
    unittest.main()
